<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const bills=ref<any[]>([]),leases=ref<any[]>([]),showGenerate=ref(false),showPayment=ref(false),error=ref(''),gen=ref({lease_id:'',period_start:'',idempotency_key:''}),pay=ref({reference:'',payer:'',amount:0,bill_id:'',allocation:0});async function load(){const[b,l]=await Promise.all([api.get('/bills',{params:{page:1,page_size:100}}),api.get('/leases',{params:{page:1,page_size:100,status:'active'}})]);bills.value=b.data.items||[];leases.value=l.data.items||[]}async function generate(){error.value='';try{await api.post('/bills/generate',gen.value);showGenerate.value=false;await load()}catch(e:any){error.value=e.response?.data?.error?.message||'生成账单失败'}}async function payment(){error.value='';try{await api.post('/payments',{reference:pay.value.reference,payer:pay.value.payer,amount:pay.value.amount,allocations:[{bill_id:pay.value.bill_id,amount:pay.value.allocation}]});showPayment.value=false;await load()}catch(e:any){error.value=e.response?.data?.error?.message||'收款核销失败'}}async function adjust(id:string,kind:string){const amount=Number(prompt(kind==='discount'?'请输入减免金额':'请输入滞纳金金额')||0);const reason=prompt('请输入调整原因')||'';if(amount>0&&reason){await api.post(`/bills/${id}/adjustments`,{kind,amount,reason});await load()}}function outstanding(x:any){return x.Amount+x.Penalty-x.Discount-x.Paid}onMounted(load)</script><template><div class="page"><div class="page-title"><div><h1>账单收款</h1><p>幂等生成周期账单，处理滞纳金、减免、部分支付和核销</p></div><div class="action-group"><button class="secondary-button" @click="showPayment=true">登记收款</button><button class="primary-button" @click="showGenerate=true">＋ 生成账单</button></div></div><div class="stat-grid"><div class="stat-card"><span>账单数量</span><strong>{{bills.length}}</strong></div><div class="stat-card"><span>未结清</span><strong>{{bills.filter(x=>outstanding(x)>0).length}}</strong></div><div class="stat-card"><span>已结清</span><strong>{{bills.filter(x=>x.Status==='paid').length}}</strong></div><div class="stat-card"><span>应收余额</span><strong style="font-size:20px">{{bills.reduce((n,x)=>n+outstanding(x),0)}}</strong></div></div><section class="card"><table v-if="bills.length" class="data-table"><thead><tr><th>账期</th><th>应收</th><th>滞纳金</th><th>减免</th><th>已收</th><th>剩余</th><th>状态</th><th>调整</th></tr></thead><tbody><tr v-for="x in bills" :key="x.ID"><td>{{String(x.PeriodStart).slice(0,10)}} 至 {{String(x.PeriodEnd).slice(0,10)}}</td><td>{{x.Amount}}</td><td>{{x.Penalty}}</td><td>{{x.Discount}}</td><td>{{x.Paid}}</td><td><strong>{{outstanding(x)}}</strong></td><td><span class="status-badge" :class="x.Status">{{x.Status}}</span></td><td><div class="action-group"><button class="secondary-button" @click="adjust(x.ID,'penalty')">加滞纳金</button><button class="secondary-button" @click="adjust(x.ID,'discount')">减免</button></div></td></tr></tbody></table><div v-else class="empty-state"><b>暂无账单</b><span>请先激活租约，再生成第一个周期账单</span></div></section><div v-if="showGenerate" class="modal-mask" @click.self="showGenerate=false"><div class="modal"><div class="modal-header"><h3>生成周期账单</h3><button class="close-button" @click="showGenerate=false">×</button></div><div class="modal-body"><div class="form-grid"><label class="full"><span>生效租约 *</span><select v-model="gen.lease_id"><option value="">请选择租约</option><option v-for="x in leases" :key="x.ID" :value="x.ID">{{x.PropertyID.slice(0,8)}} · {{String(x.StartDate).slice(0,10)}} 至 {{String(x.EndDate).slice(0,10)}}</option></select></label><label><span>账期开始 *</span><input v-model="gen.period_start" type="date"></label><label><span>幂等键 *</span><input v-model="gen.idempotency_key" placeholder="例如 bill-2026-08-lease1"></label></div><p v-if="error" class="form-error">{{error}}</p></div><div class="modal-footer"><button class="secondary-button" @click="showGenerate=false">取消</button><button class="primary-button" @click="generate">生成账单</button></div></div></div><div v-if="showPayment" class="modal-mask" @click.self="showPayment=false"><div class="modal"><div class="modal-header"><h3>登记收款与核销</h3><button class="close-button" @click="showPayment=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>支付流水号 *</span><input v-model="pay.reference"></label><label><span>付款人 *</span><input v-model="pay.payer"></label><label><span>收款金额 *</span><input v-model.number="pay.amount" type="number"></label><label><span>核销账单 *</span><select v-model="pay.bill_id"><option value="">请选择未结清账单</option><option v-for="x in bills.filter(v=>outstanding(v)>0)" :key="x.ID" :value="x.ID">{{String(x.PeriodStart).slice(0,10)}} · 剩余 {{outstanding(x)}}</option></select></label><label><span>本次核销金额 *</span><input v-model.number="pay.allocation" type="number"></label></div><p v-if="error" class="form-error">{{error}}</p></div><div class="modal-footer"><button class="secondary-button" @click="showPayment=false">取消</button><button class="primary-button" @click="payment">确认收款</button></div></div></div></div></template>